// Builds dist/data/weapon-experience.js: the total experience a primary weapon needs for each level
// (db/source/wiki_weapon_experience.json, the wiki Attachments "Weapon Experience" table). The gear
// view shows it next to each attachment's unlock level. Do not edit the output.
// Usage: node scripts/build-weapon-experience.mjs
import { readFile, writeFile } from 'node:fs/promises';

export async function buildWeaponExperience() {
  const source = JSON.parse(await readFile(new URL('../db/source/wiki_weapon_experience.json', import.meta.url), 'utf8'));
  // Table rows "| 5 || 1600 || 1000 || ..." -> level and total experience; level 1 has none ("-").
  const levels = {};
  for (const m of source.section.matchAll(/^\|\s*(\d+)\s*\|\|\s*([\d,]+)\s*\|\|/gm)) levels[m[1]] = Number(m[2].replace(/,/g, ''));
  if (!Object.keys(levels).length) throw new Error('wiki_weapon_experience.json: no level rows in the Weapon Experience table');
  return { source: { page: source.source, revision: source.revision }, levels };
}

if (import.meta.url === `file:///${process.argv[1].replaceAll('\\', '/').replace(/^\//, '')}`) {
  const data = await buildWeaponExperience();
  await writeFile(new URL('../dist/data/weapon-experience.js', import.meta.url), `// Generated by scripts/build-weapon-experience.mjs from the Helldivers Wiki Attachments page
// (CC BY-NC-SA 4.0). Total experience a primary weapon needs to reach each level. Do not edit.
export const weaponExperienceSource = ${JSON.stringify(data.source)};
export const weaponExperience = ${JSON.stringify(data.levels)};
`);
  console.log(`weapon levels ${Object.keys(data.levels).join(', ')}`);
}
